def _mlp_predict_arch_fast(feats, arch):
    try:
        if _HAS_NP:
            m = _MODELS.get(arch) or _MODELS.get("GLOBAL")
            if not m:
                return 0.5
            import numpy as np
            a = np.array(feats, dtype=np.float64)
            mean = np.array(m["mean"]); std = np.array(m["std"])
            xn = (a - mean) / std
            h1 = np.maximum(xn @ np.array(m["W1"]) + np.array(m["b1"]), 0)
            h2 = np.maximum(h1 @ np.array(m["W2"]) + np.array(m["b2"]), 0)
            z = h2 @ np.array(m["W3"]) + np.array(m["b3"])[0]
            if z>20: return 1.0
            if z<-20: return 0.0
            return 1.0/(1.0+math.exp(-z))
    except:
        pass
    return 0.5




