_W_STALL_2_bias = [0.07188423226527936]

def _mlp_predict_arch(feats, arch):
    # arch in FAST,WALL,SPREAD,MIRROR,DEFAULT,STALL
    try:
        if _HAS_NP:
            a=np.array(feats, dtype=np.float64)
            if arch=="FAST":
                h1 = np.maximum(0, a.dot(np.array(_W_FAST_0_coef)) + np.array(_W_FAST_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_FAST_1_coef)) + np.array(_W_FAST_1_bias))
                out = h2.dot(np.array(_W_FAST_2_coef).flatten()) + np.array(_W_FAST_2_bias)[0]
            elif arch=="WALL":
                h1 = np.maximum(0, a.dot(np.array(_W_WALL_0_coef)) + np.array(_W_WALL_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_WALL_1_coef)) + np.array(_W_WALL_1_bias))
                out = h2.dot(np.array(_W_WALL_2_coef).flatten()) + np.array(_W_WALL_2_bias)[0]
            elif arch=="SPREAD":
                h1 = np.maximum(0, a.dot(np.array(_W_SPREAD_0_coef)) + np.array(_W_SPREAD_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_SPREAD_1_coef)) + np.array(_W_SPREAD_1_bias))
                out = h2.dot(np.array(_W_SPREAD_2_coef).flatten()) + np.array(_W_SPREAD_2_bias)[0]
            elif arch=="MIRROR":
                h1 = np.maximum(0, a.dot(np.array(_W_MIRROR_0_coef)) + np.array(_W_MIRROR_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_MIRROR_1_coef)) + np.array(_W_MIRROR_1_bias))
                out = h2.dot(np.array(_W_MIRROR_2_coef).flatten()) + np.array(_W_MIRROR_2_bias)[0]
            elif arch=="DEFAULT":
                h1 = np.maximum(0, a.dot(np.array(_W_DEFAULT_0_coef)) + np.array(_W_DEFAULT_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_DEFAULT_1_coef)) + np.array(_W_DEFAULT_1_bias))
                out = h2.dot(np.array(_W_DEFAULT_2_coef).flatten()) + np.array(_W_DEFAULT_2_bias)[0]
            elif arch=="STALL":
                h1 = np.maximum(0, a.dot(np.array(_W_STALL_0_coef)) + np.array(_W_STALL_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_STALL_1_coef)) + np.array(_W_STALL_1_bias))
                out = h2.dot(np.array(_W_STALL_2_coef).flatten()) + np.array(_W_STALL_2_bias)[0]
            else:
                # fallback to FAST
                h1 = np.maximum(0, a.dot(np.array(_W_FAST_0_coef)) + np.array(_W_FAST_0_bias))
                h2 = np.maximum(0, h1.dot(np.array(_W_FAST_1_coef)) + np.array(_W_FAST_1_bias))
                out = h2.dot(np.array(_W_FAST_2_coef).flatten()) + np.array(_W_FAST_2_bias)[0]
            if isinstance(out, np.ndarray):
                out=float(out)
            if out>20:
                return 1.0
            if out<-20:
                return 0.0
            return 1.0/(1.0+math.exp(-out))
    except Exception as e:
        pass
    # Pure python fallback - use FAST model as generic
    # For simplicity fallback to generic combined model if per-arch not found
    # We'll implement FAST fallback
    try:
        # Use FAST weights as fallback
        h1=[0.0]*128
        for j in range(128):
            s=_W_FAST_0_bias[j]
            for i in range(20):
                s+=feats[i]*_W_FAST_0_coef[i][j]
            h1[j]= s if s>0 else 0.0
        h2=[0.0]*64
        for j in range(64):
            s=_W_FAST_1_bias[j]
            for i in range(128):
                s+=h1[i]*_W_FAST_1_coef[i][j]
            h2[j]= s if s>0 else 0.0
        s=_W_FAST_2_bias[0]
        for i in range(64):
            s+=h2[i]*_W_FAST_2_coef[i][0]
        if s>20:
            return 1.0
        if s<-20:
            return 0.0
        return 1.0/(1.0+math.exp(-s))
    except:
        return 0.5


def _extract_features_v42(obs, me_idx, opp_idx):
    try:
        cur=obs.get("current") or {}
        turn=int(cur.get("turn") or 0)
        players=cur.get("players") or []
        if len(players)<2:
            return None
        me=players[me_idx]
        opp=players[opp_idx]
        my_active=me.get("active") or {}
        opp_active=opp.get("active") or {}
        my_bench=me.get("bench") or []
        opp_bench=opp.get("bench") or []
        my_deck=int(me.get("deckCount") or 0)
        opp_deck=int(opp.get("deckCount") or 0)
        my_hand=len(me.get("hand") or [])
        opp_hand=len(opp.get("hand") or [])
        def count_water(discard):
            cnt=0
            for d in discard or []:
                if isinstance(d, dict):
                    cid=d.get("id")
                    if cid is None:
                        continue
                    c=card(cid)
                    if c and c.get("en")==3:
                        cnt+=1
            return cnt
        my_water=count_water(me.get("discard"))
        opp_water=count_water(opp.get("discard"))
        def prize_taken(p):
            prize=p.get("prize") or []
            return sum(1 for x in prize if x is None)
        my_prize_taken=prize_taken(opp)
        opp_prize_taken=prize_taken(me)
        def hp_ratio(active):
            try:
                hp=int(active.get("hp") or 0)
                maxhp=int(active.get("maxHp") or hp or 1)
                return hp/maxhp if maxhp else 0, hp, maxhp, len(active.get("energies") or [])
            except:
                return 0,0,0,0
        my_hp_ratio, my_hp, my_maxhp, my_en = hp_ratio(my_active)
        opp_hp_ratio, opp_hp, opp_maxhp, opp_en = hp_ratio(opp_active)
        def bench_hp_ratio(bench):
            total=0
            max_total=0
            for b in bench:
                if isinstance(b, dict):
                    hp=int(b.get("hp") or 0)
                    maxhp=int(b.get("maxHp") or hp or 1)
                    total+=hp
                    max_total+=maxhp
            return (total/max_total if max_total else 0), len(bench)
        my_bench_ratio, my_bench_n = bench_hp_ratio(my_bench)
        opp_bench_ratio, opp_bench_n = bench_hp_ratio(opp_bench)
        feats=[
            turn/50.0,
            my_deck/60.0,
            opp_deck/60.0,
            my_hand/10.0,
            opp_hand/10.0,
            my_bench_n/5.0,
            opp_bench_n/5.0,
            my_hp_ratio,
            opp_hp_ratio,
            my_en/5.0,
            opp_en/5.0,
            my_bench_ratio,
            opp_bench_ratio,
            my_water/15.0,
            opp_water/15.0,
            my_prize_taken/6.0,
            opp_prize_taken/6.0,
            (my_maxhp or 0)/400.0,
            (opp_maxhp or 0)/400.0,
            (my_hp - opp_hp)/400.0,
        ]
        return feats
    except Exception:
        return None


